export function createStudioUI({state,esc,btn,field,openDialog,formDialog,api,endpoint,refresh}) {
  const title=code=>({blocked_missing_brand_assets:'Materiais oficiais pendentes',blocked_higgsfield_not_configured:'Integração de criação indisponível',blocked_higgsfield_executor_unvalidated:'Executor ainda não validado',blocked_production_review_required:'Decisões de produção pendentes',blocked_openai_not_configured:'OpenAI não configurada',blocked_openai_image_access:'Acesso à geração pendente',blocked_first_generation_required:'Primeira geração ainda não realizada'}[code]||'Produção pendente');
  const lines=value=>esc(String(value||'').replace(/\\n/g,'\n'));
  function summary(){return (state().production||[]).map(p=>`<section class="notice-box studio-production-summary"><strong>${esc(title(p.state))}</strong><p>A entrega existente aguarda as dependências de produção. Veja o que falta e como continuar.</p>${btn('Ver produção existente','studio-production',`data-id="${esc(p.contentId)}"`,'secondary')}</section>`).join('');}
  function detail(p){
    const c=state().records.content.find(c=>c.id===p.contentId),isOpenAI=p.executor.provider==='openai';
    const executor=(isOpenAI?'API OpenAI':'Integração anterior')+' · '+(p.executor.state==='not_configured'?'não configurada':p.executor.state==='model_accessible_unvalidated'?'modelo acessível; geração não validada':'validação pendente');
    const facts=[['Estado',title(p.state)],['Entrega existente','Versão '+p.sourceVersion],['Verificação registrada',p.storedVersion?'Versão '+p.storedVersion:'Ainda não registrada'],['Executor',executor],['Geração','Não iniciada'],['Arquivo final','Não produzido'],['Formato solicitado','Uma imagem · 1080 × 1080 · PNG ou JPG'],['Aprovação humana','Não solicitada; não há peça final']];
    const blockers=p.blockers.map(b=>`<section class="notice-box"><strong>${esc(title(b.code))}</strong><p>${esc(b.message)}</p>${(b.missing||[]).map(m=>`<p><strong>${esc(m.material)}</strong><br>${esc(m.why)}<br>${esc(m.where)}</p>`).join('')}</section>`).join('');
    const decision=p.decision?`<section class="notice-box"><strong>Decisão criativa fornecida pelo usuário · versão ${p.decision.version}</strong><p class="prewrap">${lines(p.decision.text)}</p><p>CTA removido. Direção registrada; a aprovação da peça final ainda não foi solicitada.</p></section>`:'';
    const specification=`<details class="operation-details"><summary>Briefing preservado e especificação</summary><h3>Objetivo</h3><p>${esc(p.specification.objective)}</p><h3>Público</h3><p>${esc(p.specification.audience||'Não informado')}</p><h3>${p.decision?'Texto final confirmado':'Texto de origem · ainda requer confirmação final'}</h3><p class="prewrap">${lines(p.specification.exactText.source)}</p><h3>Direção da imagem-base</h3><p class="prewrap">${lines(p.specification.artDirection)}</p>${p.decision?`<h3>Composição</h3><p>${esc(p.specification.composition)}</p><p>Margens de 80 px. Área segura de 920 × 920 px. ${esc(p.specification.alignment)}</p><h3>Briefing original preservado</h3><p class="prewrap">${lines(c.visualPrompt)}</p>`:'<p>Margens, área segura e texto final ainda precisam ser definidos.</p>'}<h3>Critérios de aprovação</h3><ul>${p.specification.approvalCriteria.map(s=>`<li>${esc(s)}</li>`).join('')}</ul><p>Nenhuma revisão técnica, factual ou visual de uma peça final foi realizada.</p></details>`;
    const trace=`<details class="operation-details"><summary>Origem e rastreabilidade</summary><p>Execução criativa: ${esc(p.sourceJobId||'Origem não vinculada')}</p><p>Campanha: ${esc(p.campaignId||'Nenhuma campanha vinculada na entrega original')}</p><p>Hash do briefing, não da imagem: <code>${esc(p.sourceHash)}</code></p>${p.executor.access?.requestId?`<p>Consulta ao modelo: <code>${esc(p.executor.access.requestId)}</code>. Essa consulta não gerou imagem.</p>`:''}</details>`;
    openDialog('Produção visual · '+c.title,`<div class="studio-production-detail"><p class="dialog-explainer">Esta é a mesma entrega do Estúdio. A verificação local registra dependências; gerar uma imagem exige uma ação explícita.</p><dl class="publication-facts">${facts.map(([key,value])=>`<div><dt>${esc(key)}</dt><dd>${esc(value)}</dd></div>`).join('')}</dl>${p.stale?'<p class="operation-blocker">O conteúdo mudou depois da verificação. Atualize o diagnóstico; a versão anterior continua no histórico.</p>':''}${decision}${blockers}${specification}${trace}<div class="detail-actions">${btn('Registrar verificação','studio-check',`data-id="${esc(p.contentId)}"`)}${btn('Materiais oficiais','studio-materials','','secondary')}${isOpenAI?btn('Conferir acesso à OpenAI','studio-openai-check',`data-id="${esc(p.contentId)}"`,'secondary'):''}<a class="p-button secondary" href="#/integrations" data-action="close-dialog">${isOpenAI?'Integração OpenAI':'Conexões de criação'}</a></div></div>`,true);
  }
  function materials(){
    const s=state(),official=s.brandMaterials||{},candidate=(s.production||[]).find(p=>p.candidates?.hash)?.candidates,m=official.confirmedBy?official:candidate||{},org=s.company.id;
    const images=s.assets.filter(a=>a.mime.startsWith('image/')),fonts=s.assets.filter(a=>a.mime.startsWith('font/'));
    const provenance=!official.confirmedBy&&candidate?`<div class="notice-box wide"><strong>Materiais localizados · aguardando sua confirmação</strong><p>Os campos abaixo são sugestões extraídas dos arquivos da EME. Ainda não estão registrados como oficiais.</p><p class="studio-source">${esc(candidate.sources?.logo||'')}<br>${esc(candidate.sources?.font||'')}<br>${esc(candidate.sources?.colors||'')}</p>${images.some(a=>a.id===m.logoAssetId)?`<img class="studio-brand-preview" src="${esc(images.find(a=>a.id===m.logoAssetId).url)}" alt="Logo candidato da EME">`:''}</div>`:'';
    formDialog('Materiais oficiais · '+s.company.name,`<p class="dialog-explainer wide">Confira os arquivos e as cores da empresa antes de confirmar. A confirmação dos materiais não aprova a peça final.</p>`+provenance+field('logoAssetId','Versão oficial do logo','select',m.logoAssetId||'',[['','Selecione o arquivo'],...images.map(a=>[a.id,a.name])],true)+field('fontAssetId','Arquivo da fonte oficial','select',m.fontAssetId||'',[['','Selecione a fonte'],...fonts.map(a=>[a.id,a.name])],true)+field('fontFamily','Família da fonte','text',m.fontFamily||'',[],true)+field('background','Cor de fundo · #RRGGBB','text',m.colors?.background||'',[],true)+field('foreground','Cor do texto · #RRGGBB','text',m.colors?.foreground||'',[],true)+field('accent','Cor de destaque · #RRGGBB','text',m.colors?.accent||'',[],true)+field('confirmed','Confirmo que os arquivos e as cores são os materiais oficiais aprovados desta empresa.','checkbox',false),async d=>{
      if(state().company.id!==org)throw new Error('A empresa ativa mudou. Confira os materiais novamente.');
      await api(endpoint('studio/materials'),'POST',{logoAssetId:d.logoAssetId,fontAssetId:d.fontAssetId,fontFamily:d.fontFamily,colors:{background:d.background,foreground:d.foreground,accent:d.accent},confirmed:d.confirmed===true});await refresh(false);
    },'Salvar materiais oficiais',true);
  }
  return {summary,detail,materials};
}
